type Topic = { slug: string; title: string; excerpt: string; lane: string; image: string; datePublished: '2026-08-23'; sections: { title: string; paragraphs: string[] }[] };

const topics: Topic[] = [
  { slug:'filipino-back-office-inbox-triage-coordinator', title:'How to scope Filipino back-office inbox triage', excerpt:'Create a reviewable inbox lane for sorting, labeling, and routing operational messages without letting a coordinator make commitments.', lane:'back-office inbox triage', image:'/images/blog-2026-08-23-back-office-inbox-triage.png', datePublished:'2026-08-23', sections:[
    {title:'Define the message boundary',paragraphs:['A back-office inbox is not one task. It may contain routine requests, missing documents, account questions, internal instructions, and messages that change a customer commitment. A Filipino coordinator needs an intake rule that names the allowed sender types, folders or labels, required fields, and finished handoff. The first queue might cover categorizing approved operational messages and attaching them to an existing record.','Separate sorting from answering. The coordinator can identify the subject, date, reference number, requested action, and missing context when those fields are visible. A client-side owner should decide what a message means for policy, service, payment, employment, or a customer relationship. That boundary keeps helpful organization from becoming an accidental promise.']},
    {title:'Write routing rules that survive ambiguity',paragraphs:['Use labels that describe the next action rather than the worker’s guess about importance: ready for routine reply, waiting for source, owner decision, duplicate, or restricted. Each label needs an example and a named destination. If a message could fit two queues, preserve both plausible readings and route the question instead of selecting the one that makes the inbox look clear.','A useful escalation includes the original message, received time, related record, rule considered, missing fact, and exact question. Do not paraphrase away a qualifier that changes meaning. For teams working across Philippine and client schedules, a dated route note gives the next owner enough context to continue without searching private chat.']},
    {title:'Protect the inbox as a system of record',paragraphs:['List the mailbox, ticketing system, approved labels, retention expectations, and permission level in the role brief. Use named accounts and approved authentication controls. Avoid forwarding sensitive material to personal addresses or copying entire threads into a broad spreadsheet. Access should follow the first queue, with a review date and removal owner.','Quality review should sample a routine message, an incomplete request, and a message that must stop. Check whether the original source remains available, the label matches the rule, and the escalation preserves uncertainty. Corrections should become written examples only after the responsible owner approves the interpretation.']},
    {title:'Measure queue health without promising outcomes',paragraphs:['Track messages received, categorized, routed, returned, waiting for evidence, escalated, duplicated, and aging. Those fields help the manager see where the operating rule is unclear. They do not prove response speed, customer satisfaction, revenue, retention, or any other business result. A rise in escalations may show that the coordinator is correctly stopping at a decision boundary.','Review the scorecard with examples, not just totals. If many items share the same missing field, improve intake instructions. If many items require judgment, narrow the first queue. The goal is a teachable Philippines staffing lane that an owner can inspect and correct.']},
    {title:'Plan continuity across shifts',paragraphs:['Keep current state, last source checked, next owner, handoff time, and access limitation together. A substitute should not reconstruct the queue from unread messages or assume silence means approval. The record should show whether the item is waiting on a sender, a system owner, or a business decision.','Use a short review cadence during launch and record accepted corrections with an effective date. When an owner changes a rule, identify earlier items that may be affected. This makes the queue safer to resume and prevents a new worker from learning an undocumented exception through trial and error.']},
    {title:'Decide whether the role is ready',paragraphs:['Before expanding the inbox lane, ask a manager who did not write the brief to explain what enters, what finished looks like, what examples cover, and which messages require escalation. If the answer depends on personal memory, narrow the queue or settle the missing rule first.','A coordinator can prepare a clean route, but cannot approve a refund, interpret a contract, change access, make an employment determination, or promise a customer outcome. Those decisions stay with the authorized owner.']}
  ]},
  { slug:'filipino-customer-renewal-records-assistant', title:'How to use Filipino support for customer renewal records', excerpt:'Organize renewal dates, source notes, and open questions while leaving commercial decisions and customer commitments with the account owner.', lane:'customer renewal records', image:'/images/blog-2026-08-23-customer-renewal-records.png', datePublished:'2026-08-23', sections:[
    {title:'Make renewal evidence explicit',paragraphs:['Renewal preparation should start with an account identifier, agreement or subscription reference, relevant dates, approved source, current owner, and a defined finish point. A Filipino assistant can collect and compare those records when the rules are written. A blank date, conflicting term, or missing approval should remain visible rather than being filled from memory or a nearby account.','The work is evidence preparation, not a forecast. Keep observed renewal language separate from an internal assumption about likelihood. The assistant may flag an approaching date or missing record; the account owner decides whether to contact the customer, change a commercial term, or accept an exception.']},
    {title:'Separate dates from decisions',paragraphs:['Use distinct states for source found, date confirmed, clarification needed, owner review, and closed. A record should show where each date came from and when it was checked. If a portal and a signed document disagree, attach both references and ask which source governs. Never resolve a commercial conflict merely to clear a dashboard.','A decision-ready handoff states the account, evidence, discrepancy, consequence if unresolved, and owner question. It should not label an account safe, committed, retained, or at risk unless an authorized owner has defined and approved that conclusion.']},
    {title:'Design a privacy-aware record',paragraphs:['Renewal files can contain contact information, contract terms, and internal notes. Grant only the permissions needed for the first queue, use named accounts, and record the approving owner and review date. Avoid exporting a whole customer list when a filtered record is enough. Keep the source link and minimum necessary fields together.','Sample one ordinary account, one record with a missing term, and one with conflicting sources. The reviewer checks whether the assistant preserved original wording, minimized copied data, and routed the decision to the right owner. Corrections should distinguish transcription from commercial interpretation.']},
    {title:'Coordinate the calendar carefully',paragraphs:['A date list becomes useful only when the manager knows the source, time zone, reminder rule, and next action. The assistant can prepare a calendar view from approved records and identify items that need review. They should not send a customer-facing renewal promise or select a new term because a date is approaching.','For a Philippines-based team, record the handoff timestamp and owner response window. A waiting state should say whether the account owner, legal reviewer, finance reviewer, or customer must provide the next fact. This avoids repeated follow-ups that add noise without resolving the source question.']},
    {title:'Use measures as inspection signals',paragraphs:['Track records checked, missing references, conflicting dates, owner waits, returned packets, and accepted corrections. These measures describe preparation quality and queue condition. They are not claims about renewal rate, revenue, customer value, or commercial performance. A small, well-described queue is more useful than a large list built from uncertain assumptions.','Review repeated exceptions at the rule level. If the same contract type needs a different checklist, name that branch rather than adding a vague instruction. Expand only after a reviewer can reproduce the date check from the source and explain what remains outside the role.']},
    {title:'Keep authority with the account owner',paragraphs:['The assistant may organize approved renewal evidence, draft a neutral question, and maintain a status log. The owner keeps authority over pricing, concessions, term changes, customer communications that create commitments, and exceptions. Those boundaries should appear beside the examples, not in a buried policy document.','A role is ready when a substitute can identify the source, check the date, record uncertainty, and route the decision without inventing context. That is the practical standard for a FilipinoOutsource.com staffing lane: visible work, limited access, and accountable handoff.']}
  ]},
  { slug:'filipino-knowledge-base-maintenance-coordinator', title:'How to scope Filipino knowledge-base maintenance coordination', excerpt:'Keep approved help content current by checking sources, links, and review triggers without turning a coordinator into the policy owner.', lane:'knowledge-base maintenance', image:'/images/blog-2026-08-23-knowledge-base-maintenance.png', datePublished:'2026-08-23', sections:[
    {title:'Define maintenance as a checkable queue',paragraphs:['Knowledge-base maintenance should name the article, source owner, effective date, audience, required links, and review trigger. A Filipino coordinator can compare a published page with an approved source, record a broken reference, and prepare a correction packet. The coordinator should not decide a policy meaning because a sentence sounds outdated.','Start with one content family and a finite checklist. A normal item has a current source and working link. An incomplete item lacks an owner or effective date. A stop item changes an instruction, eligibility rule, safety message, or customer commitment and must go to the authorized reviewer.']},
    {title:'Preserve version context',paragraphs:['Record the page version, source version, checking time, and exact location of an issue. Keep the prior approved wording when history matters and distinguish a formatting defect from a change in operational meaning. A link that redirects may still require review if it changes the user’s path or authority.','The handoff should quote only the necessary fragment, link the source, state what differs, and ask who approves the correction. Do not silently edit a policy page to make a checklist pass. The visible record should show both the observation and the decision.']},
    {title:'Check access and publication boundaries',paragraphs:['Give the coordinator the smallest permissions needed to inspect drafts or prepare changes. If the role can edit a content system, define whether edits remain drafts and who publishes them. Use named accounts and an access review date. Never use a shared login or publish a consequential instruction without the responsible owner’s approval.','A reviewer should sample an ordinary typo, a stale link, and a disputed instruction. For each, check source, location, version, and route. This protects the boundary between content operations and the subject-matter owner who decides what the public should be told.']},
    {title:'Handle translations and accessibility separately',paragraphs:['A translated article, caption, alt text, or downloadable form can create a new review question even when the source page is correct. Record which language or asset was checked and whether the approved source covers it. A coordinator can flag inconsistency; a qualified owner decides meaning, terminology, and accessibility requirements.','Keep asset dependencies visible. If a page refers to a form that has moved, record the old and new locations and pause if the replacement changes eligibility or required information. This is especially important when content is maintained across time zones and several people can make edits.']},
    {title:'Measure maintenance without making quality claims',paragraphs:['Track pages checked, broken links, missing source owners, expired review triggers, returned drafts, and reviewer corrections. These are workflow signals, not evidence that every article is accurate, useful, compliant, or effective. Explain the sample boundary and the checklist version whenever reporting them.','If the same error recurs, improve the checklist or source ownership rather than asking the coordinator to be more careful. A written correction with an effective date is easier to teach than an informal comment attached to one page.']},
    {title:'Keep policy decisions with the owner',paragraphs:['The coordinator may inspect, document, route, and maintain approved records. They should stop when wording changes a rule, customer promise, legal interpretation, access instruction, or safety response. The owner decides whether the change is approved and whether previously published pages need review.','A manager should be able to explain the queue to a substitute: what source governs, what finish means, what examples show, and what never gets published without approval. If not, narrow the lane before adding more pages.']}
  ]},
];

