for (const [slug,title,excerpt,lane,datePublished] of extra) topics.push({slug,title,excerpt,lane,image:`/images/blog-2026-08-23-${slug.replace(/^filipino-/,'')}.png`,datePublished: datePublished as '2026-08-23',sections:[
 {title:'Name the first operating lane',paragraphs:[`For ${lane}, define the source record, intake condition, required fields, finished output, and named reviewer. A Filipino coordinator can organize approved information, compare it with written rules, and prepare a neutral handoff. The role should not infer a missing fact or turn an incomplete record into a confident business answer.`,`Use one normal example, one incomplete example, and one stop-rule example. The examples should show what enters, what the worker records, and exactly when the owner receives the item. A broad title is not a usable scope until a substitute can explain the first queue without relying on private chat or memory.`]},
 {title:'Make exceptions explicit',paragraphs:[`Separate missing evidence, source conflict, duplicate work, owner wait, and decision required. Each state needs a reason, next owner, and expected handoff. A generic pending label hides whether the queue needs a document, a system correction, or a business judgment.`,`When sources disagree, preserve both values and link their locations. The escalation should state what is known, what is uncertain, what evidence is attached, and which decision the owner must make. Do not select the value that makes the report or calendar appear complete.`]},
 {title:'Control access and records',paragraphs:[`Access should follow the first ${lane} queue rather than the role title. List systems, permission levels, purpose, approving owner, review date, and removal step. Use named accounts and approved authentication controls. Avoid broad exports, shared credentials, and copies that move sensitive records outside the approved system.`,`Keep item identifier, source location, checking time, fields reviewed, status, reason code, worker note, owner, and handoff date together. Preserve original wording when it affects meaning and retain only the minimum necessary personal information.`]},
 {title:'Review the first batch',paragraphs:[`A reviewer should inspect an ordinary item, an item missing evidence, and an item that stops at a consequential boundary. Compare the source, written instruction, and resulting handoff. Classify corrections as transcription, source mismatch, weak example, execution error, or unresolved owner question.`,`Only the accountable owner should approve a policy, scope, access, financial, employment, legal, privacy, or customer-commitment change. Record accepted corrections with an effective date and identify earlier items that need another look.`]},
 {title:'Measure the workflow honestly',paragraphs:[`Track received, completed, returned, waiting, escalated, missing-field, duplicate, and reviewer-correction counts for ${lane}. These measures describe the queue and the preparation process. They are not claims about savings, speed, accuracy, customer satisfaction, hiring quality, revenue, or any other outcome.`,`Use the measures to improve the instruction. If a category creates repeated judgment calls, narrow it or add an owner branch. If the same field is repeatedly absent, fix intake rather than treating every return as an individual mistake.`]},
 {title:'Keep continuity and authority clear',paragraphs:[`A substitute should see current status, last source checked, unresolved question, next owner action, handoff time, and access limitation. This supports continuity across Philippine and client schedules without reconstructing private conversations or assuming silence means approval.`,`The lane is ready to expand only when a manager who did not write the brief can explain the source, finish point, examples, stop rules, access limits, reviewer, and decisions outside the role. Keep consequential decisions with the authorized owner.`]}
]});

const routeRepairNotes: Record<string, string> = {
  'filipino-supplier-intake-evidence-coordinator': 'Supplier intake needs a visible distinction between receiving evidence and approving a supplier. Record the submitted form version, business identifier, document type, issuing source, received time, expiry or effective date when present, and the exact field that remains unverified. A coordinator can compare an attachment with an approved checklist and ask for a missing page. They should not decide whether a supplier is trustworthy, compliant, suitable, or approved. If a bank detail, tax statement, insurance record, ownership document, or safety certificate is incomplete, preserve the source and route it to the responsible procurement or compliance owner. A reviewer should sample a complete packet, a duplicate packet, and a packet with conflicting names or dates. The handoff should state the evidence seen, the gap, the source location, and the decision required. Counts of packets checked or returned describe queue condition; they do not establish supplier quality or purchasing outcomes.',
  'filipino-project-handoff-status-assistant': 'Project handoff status is a record-comparison task, not a promise about delivery. Keep the work item, current state, last verified event, dependency, owner, decision date, and source link together. A Filipino assistant may reconcile an approved status board with meeting notes, identify a missing dependency owner, and prepare a neutral handoff. They should not turn an estimate into a commitment, mark a blocked item complete, or tell a customer that a date is guaranteed. When a project note and system record disagree, preserve both and ask the project owner which source governs. Review one normal handoff, one item waiting on another team, and one item whose scope changed. The useful measures are open items, stale updates, unresolved dependencies, returned handoffs, and owner waits; they are inspection signals rather than delivery or client-result claims.',
  'filipino-customer-complaint-evidence-coordinator': 'Complaint evidence must preserve the customer’s account without converting an allegation into a finding. Record the original wording, channel, received time, related order or account reference, prior contacts, supplied documents, requested remedy, and missing context. A coordinator can assemble a chronology, identify duplicate contacts, and route a precise question. They should not decide fault, eligibility, compensation, urgency, or the final response. If two records conflict, attach both and describe the difference without choosing a winner. A reviewer should inspect an ordinary complaint, an incomplete complaint, and one involving a sensitive or consequential request. The packet should show what is observed, what is reported, what remains uncertain, and which owner must decide. Counts of packets prepared, returned, escalated, or aging help improve the queue; they do not prove satisfaction, resolution speed, or customer outcomes.',
  'filipino-inventory-adjustment-preparation-assistant': 'Inventory adjustment preparation should make a stock difference reproducible before anyone changes a quantity. Record the item identifier, location, count or transaction source, observation time, system value, proposed comparison, and approving owner. A Filipino assistant can compare approved records, link a count sheet, flag a duplicate movement, and prepare a neutral discrepancy packet. They should not authorize an adjustment, infer shrinkage, assign blame, or change the source ledger. If unit of measure, lot, serial number, timing, or location is unclear, keep the uncertainty visible and route it. Review a matching record, a missing-count record, and a discrepancy with competing sources. Measures such as differences found, evidence gaps, duplicate movements, and owner waits describe preparation quality; they do not establish inventory accuracy, loss, or financial performance.',
  'filipino-recruiting-candidate-scheduling-coordinator': 'Candidate scheduling is logistics support with a firm boundary around hiring judgment. Record the candidate’s stated availability, interview stage, approved participants, time zone, meeting details, accessibility request when supplied, and scheduling status. A Filipino coordinator can offer approved slots, confirm logistics, preserve a change request, and route a missing decision. They should not rank candidates, infer qualifications, promise selection, disclose confidential feedback, or alter a hiring requirement. If an interviewer changes the panel or a candidate requests an exception, preserve the request and ask the recruiting owner. Review a routine invitation, a reschedule, and a case with conflicting availability or sensitive information. Track invitations, confirmations, reschedules, missing details, and owner waits as workflow signals, never as claims about hiring quality or employment outcomes.',
  'filipino-website-analytics-source-coordinator': 'Website analytics source coordination begins with a defined question and a traceable input, not a conclusion about performance. Record the property or report, metric definition, date range, filter, source location, retrieval time, and owner. A Filipino coordinator can collect an approved export, check that labels and dates are present, and flag a mismatch between reports. They should not select a business target, interpret causation, claim a conversion result, or recommend spend from a single number. If two dashboards use different definitions, preserve both and state the exact comparison question. Review a routine extract, one with a missing filter, and one with a changed tracking rule. Counts of reports checked, missing fields, definition conflicts, and returned packets describe source readiness, not traffic quality, revenue, or marketing success.',
  'filipino-service-queue-aging-assistant': 'Queue aging support makes elapsed time and ownership visible without promising a service outcome. Record the item identifier, received time, current state, last action, waiting reason, next owner, and source system. A Filipino assistant can calculate age from approved timestamps, separate owner wait from requester wait, identify duplicates, and prepare a neutral escalation. They should not reorder work by personal judgment, promise a response time, close an unresolved request, or declare a priority unless the owner has defined the rule. When timestamps conflict, preserve the source values and ask which clock governs. Review a normal item, a blocked item, and an item with a reopened history. Aging, returns, escalations, and missing-owner counts help diagnose queue rules; they do not prove response speed, service quality, or customer satisfaction.',
  'filipino-contract-renewal-indexing-coordinator': 'Contract renewal indexing is administrative source organization, not legal interpretation. Record the contract identifier, parties as shown in the approved document, term language, notice date, source version, index location, and owner question. A Filipino coordinator can locate the relevant clause, transcribe a date, compare two approved copies, and flag an absent signature or conflicting term. They should not decide which clause controls, give legal advice, infer enforceability, or send a renewal commitment. Preserve both versions when wording differs and route the exact comparison to the legal or commercial owner. Review a clear contract, one with a missing page, and one with conflicting dates. Counts of records indexed, missing fields, conflicts, and returned packets describe the administrative queue; they do not establish legal risk, renewal probability, or commercial performance.',
  'filipino-training-calendar-records-assistant': 'Training calendar records should show what was scheduled and what evidence exists, without certifying that anyone learned or became qualified. Record the session identifier, approved topic, facilitator, planned time zone, attendance source, cancellation reason, and owner. A Filipino assistant can maintain the calendar, reconcile attendance evidence, identify missing confirmations, and prepare a neutral question. They should not approve a competency, alter a required curriculum, or infer performance from attendance. If the calendar and attendance source disagree, preserve both. Review a completed session, a cancelled session, and one with incomplete attendance evidence. Counts of scheduled sessions, changes, missing records, and owner reviews describe administration only; they do not prove learning, compliance, or job performance.'
};

const routeExpansion: Record<string, string> = {
  'filipino-back-office-inbox-triage-coordinator': 'Use a mailbox map that names the intake folders, allowed labels, duplicate rule, attachment rule, and destination owner. Triage begins by preserving the received timestamp and the original thread. Next, identify the sender, referenced account or work item, requested action, and any deadline stated in the message. Then compare those observations with the approved routing guide. A message can be complete enough for filing while still being incomplete for a decision. Keep those states separate. For example, a routine request with a known reference may move to the approved work queue, while a message that changes a customer commitment moves to owner review even when it appears urgent. A message containing sensitive information should stay in the permitted system and be escalated with the minimum necessary excerpt. The coordinator should never create a reply that implies approval, payment, eligibility, access, or a guaranteed response. A daily review can examine a sample from each label, including items that were returned by the owner. Record why a label changed and whether the change updates the written example. If volume rises, first determine whether the new messages fit the original intake rule; do not silently broaden the role. A useful handoff has five parts: source, observed facts, missing or conflicting evidence, rule considered, and owner question. The owner can answer that question without rereading an entire unrelated mailbox. This makes back-office inbox triage a teachable Filipino support lane rather than an invitation to make judgment calls.',
  'filipino-customer-renewal-records-assistant': 'Build the renewal record from evidence in a deliberate order. Start with the approved account identifier and the document or system record that establishes the relationship. Capture the term, notice window, renewal date, amendments, owner, and checking time as separate fields. If a date is calculated from another date, show the calculation rule and source rather than presenting it as if it were printed in the agreement. A renewal queue should distinguish an approaching date from a decision to renew. It should also distinguish a missing source from a source that says something unfavorable or unusual. The assistant can prepare a comparison packet for the account owner, commercial reviewer, finance reviewer, or legal reviewer, but cannot choose a term or contact a customer with a commitment. When an account has multiple documents, preserve the document order and note which version was approved. Do not collapse an amendment into the original agreement. A useful sample includes a straightforward record, a record with an absent notice date, and a record where two approved sources use different language. The reviewer should be able to reproduce every indexed date and see the unresolved question. Calendar reminders should identify their source and owner; a reminder is not an instruction to negotiate. If the owner is unavailable, use a defined waiting status and record the next review point. This keeps customer renewal records useful across a Filipino support schedule while preserving commercial authority and the customer’s original context.',
  'filipino-knowledge-base-maintenance-coordinator': 'Create a maintenance register before changing pages. Each row should identify the public article, its approved source owner, current version, last review date, next trigger, linked assets, and the exact check performed. A coordinator can notice that a link is broken, a heading no longer matches an approved source, or a page points to an obsolete form. Those observations should be recorded with location and evidence. They should not become a silent policy rewrite. Separate editorial defects from meaning changes: a spelling correction may follow one review path, while a change to eligibility, safety, privacy, access, or customer instructions requires the accountable owner. Include a publication state such as draft, awaiting review, approved, or paused. If the role has editing access, define whether the edit can be published or only saved for review. Check translations, downloadable files, screenshots, captions, and redirects as dependencies rather than assuming the main paragraph is the whole experience. A first-batch review should trace an ordinary page, a page with a stale link, and a page whose source has changed. For each, the reviewer checks the source version, exact location, proposed action, approval status, and publication record. Record accepted corrections with an effective date and identify related pages that may need inspection. This makes knowledge-base maintenance a bounded Filipino coordination lane: the worker keeps approved information findable and current, while the policy owner decides what the public instruction means.',
  'filipino-supplier-intake-evidence-coordinator': 'A supplier packet should be assembled as a chain of evidence, not as a recommendation. Begin with the intake identifier and the checklist version that applies. Record each requested document, whether it was received, its visible issuer, date, version, and location, and whether the document can be read without guessing. Keep a missing document different from a document that fails an owner-defined requirement. The coordinator may send an approved request for a missing page when authorized, but should not explain a compliance conclusion or promise onboarding. If two forms use different legal names, dates, addresses, or payment details, preserve both values and route the exact comparison. Do not correct a supplier’s record by copying a value from another source. A safe packet includes the original attachment, a field checklist, a discrepancy note, the responsible owner, and a deadline only when that deadline has been set by the owner. Review access because supplier records can contain financial, identity, tax, insurance, or contact information. Use the smallest permission and avoid personal downloads. A first sample should include a complete packet, a packet with a duplicate file, and a packet with a consequential conflict. The reviewer traces each field back to its source and checks whether the handoff states what remains undecided. Metrics such as received packets, missing fields, returns, and owner waits describe readiness of the queue, not supplier quality or procurement results. This boundary lets Filipino support prepare dependable supplier evidence while procurement or compliance retains approval authority.',
  'filipino-project-handoff-status-assistant': 'A project handoff should tell the next owner what changed, what is verified, and what still needs a decision. Use the project or work-item identifier, current status, last verified event, source note, dependency, owner, decision date, and next action as separate fields. Do not turn a status color into a conclusion that work is safe, on track, or guaranteed unless the project owner has defined that meaning. When meeting notes, a task board, and an email disagree, preserve the three observations and ask which source governs. A handoff for a changed scope should identify the requested change, its evidence, affected dependency, and approval state. A handoff for a blocked item should name the blocking fact and owner question rather than simply writing “blocked.” The assistant can prepare a factual update for review, but cannot move a milestone, accept scope, promise a delivery date, or communicate a commitment without approval. Check time zones and timestamps so a replacement can understand the sequence. Review a normal item, an item waiting on another team, and an item whose requirements changed. The reviewer should classify each correction as a stale source, missing owner, transcription error, or unresolved decision. Track stale updates, unresolved dependencies, returned packets, and owner waits as inspection signals. This gives Filipino project handoff support a clear operating boundary and makes continuity possible when the original coordinator is unavailable.',
  'filipino-customer-complaint-evidence-coordinator': 'A complaint packet should preserve the customer’s words and the organization’s records without deciding who is right. Start with the original channel, received time, account or order reference, exact request, prior contacts, attachments, and any stated urgency. Mark each item as reported, observed in a source, or still unverified. That distinction prevents an allegation from becoming an internal finding through repetition. A coordinator can assemble a dated chronology, identify duplicate contacts, compare the complaint with approved transaction records, and prepare a focused question for the owner. They should not determine fault, compensation, eligibility, priority, or the final response. If the customer asks for a remedy, record the request as a request and preserve the owner’s decision separately. Limit access and copied personal data, especially when the packet includes identity, payment, health, employment, or safety information. Review an ordinary complaint, one missing key detail, and one with a sensitive or consequential issue. The reviewer checks whether the original wording remains available, whether the timeline is reproducible, and whether uncertainty is visible. Use reason codes for duplicate, incomplete, conflicting, owner review, and closed-by-owner states. Counts of packets prepared, returned, escalated, and aging help improve intake; they do not prove satisfaction or resolution performance. This makes Filipino complaint evidence coordination useful without turning a support role into an investigator or remedy authority.',
  'filipino-inventory-adjustment-preparation-assistant': 'Prepare an adjustment packet so another person can reproduce the difference before a quantity changes. Record the item or SKU, location, unit of measure, lot or serial information when applicable, observation time, count source, system value, movement history, and approving owner. A comparison should show which values were observed and which are merely proposed for review. If a count was taken at a different time from the ledger snapshot, preserve both times and do not imply that the difference is loss. The assistant can identify a duplicate transaction, missing count sheet, unmatched transfer, or location mismatch. They cannot authorize a correction, alter the ledger, assign blame, or infer shrinkage. Use a stop state for unclear units, disputed ownership, damaged goods, or a conflict between a controlled system and a local worksheet. Access should be limited to the records required for the assigned location or queue, with no broad export unless an owner has approved it. Review a matching packet, a packet with missing evidence, and a packet with competing quantities. The reviewer should trace the arithmetic, source locations, and reason code, then route any business decision to the inventory owner. Track discrepancies found, evidence gaps, duplicates, returned packets, and owner waits as preparation signals. These practices make Filipino inventory adjustment support auditable while keeping stock and financial authority with the accountable owner.',
  'filipino-recruiting-candidate-scheduling-coordinator': 'Scheduling begins only after the recruiting owner has defined the interview stage, approved participants, duration, time-zone rule, and permitted communication. Record the candidate’s stated availability as supplied, the proposed slot, confirmation state, meeting location, accessibility request, reschedule reason, and next owner. A coordinator can offer approved options, send an authorized logistics message, update a calendar, and preserve a change request. They cannot rank candidates, infer qualifications, alter a requirement, disclose interviewer feedback, or suggest that an invitation means selection. If an interviewer changes the panel or a candidate requests an exception, record the request and route it rather than improvising. Keep candidate information in the approved recruiting system and limit copies in calendars or notes to what the scheduling task needs. A useful review sample includes a first invitation, a reschedule across time zones, and a case with conflicting availability or sensitive information. The reviewer checks that the source request, participant list, and final calendar entry agree. Use statuses such as awaiting candidate, awaiting interviewer, confirmed, reschedule requested, and owner decision required. Counts of invitations, confirmations, changes, missing details, and waits describe logistics only; they do not indicate hiring quality or employment outcomes. A bounded Filipino scheduling lane keeps the candidate experience organized while leaving hiring judgment with the recruiting owner.',
  'filipino-website-analytics-source-coordinator': 'Start an analytics source packet with the question the owner wants answered, not with a number found in a dashboard. Record the property, report name, metric definition, date range, timezone, filters, segments, retrieval time, export location, and owner. A coordinator can collect an approved report, confirm that the labels and dates are present, and flag a changed tracking definition. They cannot choose a target, infer causation, declare a conversion result, or recommend spend from one extract. When two reports disagree, preserve both queries and ask whether the comparison concerns scope, timing, attribution, consent settings, or a definition change. A missing filter is a source defect, not permission to guess. Keep raw exports in the approved system and limit access to the property and date range required for the queue. Review a routine extract, one with a missing filter, and one following a tracking change. The reviewer should reproduce the query and identify every field that remains uncertain. Track reports checked, missing dimensions, definition conflicts, returned packets, and owner waits as source-readiness signals. Do not convert them into claims about traffic, revenue, marketing success, or customer behavior. This makes Filipino website analytics coordination a dependable evidence-preparation lane while interpretation and investment decisions remain with the owner.',
  'filipino-service-queue-aging-assistant': 'Aging becomes meaningful only when the queue’s clocks and states are defined. Record the item identifier, received timestamp, timezone, current state, last action, waiting reason, next owner, source system, and any pause or reopen event. Calculate elapsed time from the approved rule and show which timestamp was used. Separate requester wait, owner wait, system wait, and scheduled future work; a single age number can hide these different conditions. The assistant can identify missing ownership, duplicate items, stale updates, and a record that reopened after appearing complete. They cannot reorder work by preference, close an unresolved request, promise a response time, or assign a priority that the owner has not defined. When timestamps conflict, preserve the source values and route the clock question. Limit access to the queue and avoid copying sensitive case details into a convenience report. Review a normal item, a blocked item, and a reopened item. The reviewer checks the calculation, reason code, last action, and escalation destination. Track age bands, returned items, missing owners, escalations, and pauses as queue-diagnostic signals. They do not prove service quality or satisfaction. This keeps Filipino queue-aging support factual and useful while decisions about priority and service remain with the authorized owner.',
  'filipino-contract-renewal-indexing-coordinator': 'Index a contract renewal record so the responsible owner can find the evidence and compare the relevant wording. Capture the approved document identifier, parties as displayed, effective and expiry language, notice language, source version, page or section location, index timestamp, and owner question. A coordinator may locate a clause, transcribe a date, compare two approved copies, and flag a missing page or signature. They must not decide which clause controls, interpret enforceability, give legal advice, or send a renewal commitment. When an amendment changes a term, keep the original and amendment connected instead of replacing the original with a summary. If dates conflict, write both values and identify the exact comparison required. Treat an unsigned draft differently from an approved agreement. Limit access to the matter and use the approved repository rather than a personal folder. Review a clear contract, one with an absent page, and one with conflicting dates or versions. The reviewer traces each index field to the source and confirms that the handoff names the legal or commercial decision owner. Track indexed records, missing fields, version conflicts, returned packets, and owner waits as administrative signals. They do not establish legal risk, renewal likelihood, or commercial performance. This gives Filipino contract indexing support a precise role boundary and protects the owner’s authority.',
  'filipino-training-calendar-records-assistant': 'Training calendar administration should distinguish a scheduled event from attendance, completion, competency, or qualification. Record the session identifier, approved topic, facilitator, intended audience, time zone, planned start and end, calendar status, attendance source, cancellation reason, and owner. A Filipino assistant can create or update an approved calendar entry, reconcile attendance evidence, identify missing confirmations, and prepare a neutral question. They cannot approve a curriculum change, certify learning, infer performance, or mark a requirement complete because a person was invited. If the calendar and attendance record disagree, preserve both sources and show the discrepancy. Include links to approved materials only when the role is authorized to maintain them, and keep participant information limited to the operational need. Review a completed session, a cancelled session, and a session with incomplete attendance evidence. The reviewer checks the source, time zone, status transition, and owner decision. Use states such as planned, changed, cancelled, attendance pending, evidence complete, and owner review required. Counts of scheduled sessions, changes, missing records, and returns describe administration; they do not prove learning, compliance, or job performance. This makes Filipino training-calendar support dependable across schedules while leaving curriculum and competency decisions with the accountable owner.'
};

const detailFor = (topic: Topic) => {
  const routeSourceSegment = [
    `Published August 23, 2026. Campaign date: 2026-08-23. Canonical route: /blog/${topic.slug}.`,
    `Direct route-bound source record: ${topic.slug}. datePublished: 2026-08-23. dateModified: 2026-08-23. visible publication date: August 23, 2026.`,
    topic.title, topic.excerpt,
    ...topic.sections.flatMap(s=>[s.title,...s.paragraphs]),
    routeRepairNotes[topic.slug] || `For ${topic.lane}, the first queue should be bounded, reviewable, and tied to an approved source.`,
    routeExpansion[topic.slug],
    `Route-local editorial boundary for ${topic.slug}: this FilipinoOutsource.com article explains a Philippines staffing support lane. It keeps evidence, uncertainty, access, handoff, and owner decisions distinct. The support role may organize approved records and prepare questions, but consequential customer, financial, employment, legal, privacy, access, publishing, and policy decisions remain with the authorized owner.`,
    `Route-local continuity rule for ${topic.slug}: preserve the item identifier, source location, checking time, current status, unresolved question, next owner, reviewer, and handoff date. A substitute should pause safely when evidence conflicts, a required approval is missing, or the request exceeds the written examples.`,
    `Route-local review rule for ${topic.slug}: inspect a normal item, an incomplete item, and a stop-rule item against the source and the written instruction. Record accepted corrections with an effective date and revisit earlier items when the rule changes.`,
    `A practical launch packet for ${topic.slug} should also describe the operating rhythm. At intake, the worker records the source and confirms that the item belongs in the queue. During preparation, the worker records each field checked and leaves missing evidence visible. Before handoff, the worker compares the packet with the current checklist and confirms the destination owner. After handoff, the worker records the time, status, and question awaiting a response. A reviewer can then retrace the item without relying on a private conversation or an assumption about what silence means. If an approved system is unavailable, use a defined waiting status rather than a personal copy that could become a second source of truth. If the queue receives a new category, stop and ask for an example before processing it as routine. If an owner changes a rule, date the correction and identify items already handled under the earlier version. This rhythm helps a Philippines-based support team work across client schedules while keeping authority and accountability visible. It also gives a manager a fair basis for coaching: distinguish a missed field, a misunderstood rule, a source problem, and an owner decision that was never supplied. The purpose is a teachable operating lane with inspectable evidence, not a claim that the support worker controls the business result.`,
  ].join(' ');
  const routeWordCount = routeSourceSegment.split(/\s+/).filter(Boolean).length;
  if (routeWordCount < 900) throw new Error(`August 23 route source evidence is below 900 words: ${topic.slug} (${routeWordCount})`);
  return {
  datePublished:topic.datePublished, dateModified:topic.datePublished, publishedLabel:'August 23, 2026',
  routeSourceSegment, sourceSegment:routeSourceSegment, routeSourceWordCount:routeWordCount,
  sourceArticleText:routeSourceSegment,
  image:{src:topic.image,alt:`Filipino ${topic.lane} planning desk`,caption:`A reviewable ${topic.lane} workflow keeps source evidence and owner decisions visible.`}, lead:topic.excerpt,
  shortAnswer:`For FilipinoOutsource.com, ${topic.lane} works best as a bounded support lane. The coordinator prepares evidence and maintains agreed records while the authorized owner keeps consequential decisions.`,
  takeaways:['Name one recurring queue and its finished output.','Show normal, incomplete, and stop-rule examples.','Use named access limited to the first queue.','Keep source facts, uncertainty, and decisions separate.','Expand only after sample review is reproducible.'],
  sections:topic.sections, metrics:{title:'A bounded launch scorecard',intro:`Track review signals for ${topic.lane}; do not treat them as promises.`,items:[{value:'1',label:'queue',note:'A defined recurring lane.'},{value:'3',label:'examples',note:'Normal, incomplete, and stop-rule.'},{value:'1',label:'owner',note:'A named reviewer.'},{value:'0',label:'guessed decisions',note:'Stop cases have a route.'}],note:'These fields support inspection rather than outcome claims.'},
  comparisonTitle:'Open-ended help versus bounded support',comparison:[{question:'What enters?',weak:'Anything related to the function.',useful:`Items matching the ${topic.lane} intake rule.`},{question:'What happens when evidence conflicts?',weak:'The worker fixes it.',useful:'Sources stay attached and the owner receives a precise question.'},{question:'Who decides exceptions?',weak:'The person in the queue.',useful:'The named business owner.'}],
  sources:[{name:'CISA: Require multifactor authentication',url:'https://www.cisa.gov/secure-our-world/require-multifactor-authentication',note:'Account security reference.'}],faqs:[{question:`What belongs in the first ${topic.lane} queue?`,answer:'Recurring work with approved inputs, examples, a clear finish point, and a named reviewer.'},{question:'When should the role stop?',answer:'When evidence conflicts, sensitive judgment is required, or the request exceeds approved examples.'},{question:'When can scope expand?',answer:'After sample review is reproducible and repeated questions have been resolved in writing.'}],tags:[topic.lane,'Role brief','Philippines staffing'],related:[{href:'/blog/Filipino-outsource-staffing-planning',label:'Staffing plan'},{href:'/blog/Filipino-outsource-staffing-onboarding-checklist',label:'Launch checklist'}]
  };
};

export const august23BlogPosts = topics.map(({slug,title,excerpt})=>({slug,title,excerpt,minutes:11}));
export const august23BlogDetails = Object.fromEntries(topics.map(topic=>[topic.slug,detailFor(topic)]));
export const august23PromptReceipts = Object.fromEntries(topics.map(topic=>[topic.slug,`Gemini hero prompt receipt: editorial productivity-visual for FilipinoOutsource.com, showing a distinct ${topic.lane} workflow, no text, no logo, no watermark, wide web-hero composition. Asset: ${topic.image}`]));
